//! Built-in documentation. Pages are the Markdown files in `docs/`, compiled in,
//! so the help always matches the build. Shortcut links like `[I](key:SetIn)` are
//! replaced with the user's current binding.

use eframe::egui::{self, RichText};
use egui_commonmark::CommonMarkViewer;

use super::App;

// DOC_IMAGES: (file name, bytes) for every file in docs/images, generated by build.rs.
include!(concat!(env!("OUT_DIR"), "/doc_images.rs"));

const MASCOT_URI: &str = "bytes://mascot.png";

/// Make the docs' screenshots (and the mascot) available to image widgets.
pub fn register_images(ctx: &egui::Context) {
    ctx.include_bytes(MASCOT_URI, include_bytes!("../../assets/mascot-small.png"));
    for (name, bytes) in DOC_IMAGES {
        ctx.include_bytes(format!("bytes://docs/images/{name}"), *bytes);
    }
}
use crate::keymap::{Action, Keymap};

/// Index of the docs page with this title (0 if there's none).
pub fn page_index(title: &str) -> usize {
    PAGES.iter().position(|(t, _)| *t == title).unwrap_or(0)
}

pub const SHORTCUTS_TITLE: &str = "Keyboard shortcuts";

const PAGES: &[(&str, &str)] = &[
    (
        "Getting started",
        include_str!("../../docs/getting-started.md"),
    ),
    (
        "Installing & updating",
        include_str!("../../docs/install.md"),
    ),
    ("The interface", include_str!("../../docs/interface.md")),
    ("Timeline & seeking", include_str!("../../docs/timeline.md")),
    ("Screenshots", include_str!("../../docs/screenshots.md")),
    ("Clips", include_str!("../../docs/clips.md")),
    ("GIFs", include_str!("../../docs/gifs.md")),
    (
        "Keyboard shortcuts",
        include_str!("../../docs/shortcuts.md"),
    ),
    ("Options & themes", include_str!("../../docs/options.md")),
    (
        "Troubleshooting",
        include_str!("../../docs/troubleshooting.md"),
    ),
];

fn action_by_name(name: &str) -> Option<Action> {
    Action::ALL.into_iter().find(|a| format!("{a:?}") == name)
}

/// Markdown links with a target: `[text](target)` → (start, end, text, target) spans.
fn links(src: &str) -> Vec<(usize, usize, &str, &str)> {
    let mut out = Vec::new();
    let mut i = 0;
    while let Some(open) = src[i..].find('[').map(|o| o + i) {
        let Some(close) = src[open..].find("](").map(|c| c + open) else {
            break;
        };
        let Some(end) = src[close..].find(')').map(|e| e + close) else {
            break;
        };
        let text = &src[open + 1..close];
        if text.contains('\n') || text.contains('[') {
            i = open + 1;
            continue;
        }
        out.push((open, end + 1, text, &src[close + 2..end]));
        i = end + 1;
    }
    out
}

/// Rewrite a docs page for in-app display.
pub fn render(src: &str, keymap: &Keymap) -> String {
    let mut out = String::with_capacity(src.len());
    let mut last = 0;
    for (start, end, text, target) in links(src) {
        let replacement = if let Some(name) = target.strip_prefix("key:") {
            match action_by_name(name).and_then(|a| keymap.get(a)) {
                Some(b) => format!("`{b}`"),
                None => "*(unbound)*".to_string(),
            }
        } else if let Some(image) = target.strip_prefix("images/") {
            // `![alt](images/x.jpg)`: keep the `!`/alt, point at the bundled bytes.
            format!("[{text}](bytes://docs/images/{image})")
        } else if target.ends_with(".md") {
            // Other pages are in the sidebar.
            format!("**{text}**")
        } else {
            continue;
        };
        out.push_str(&src[last..start]);
        out.push_str(&replacement);
        last = end;
    }
    out.push_str(&src[last..]);
    out
}

/// The shortcuts page: generated from the keymap.
pub fn shortcuts_page(keymap: &Keymap, current: bool) -> String {
    let intro = if current {
        "Your current bindings. Change them in *Options → Shortcuts*."
    } else {
        "Default bindings. Every one can be changed in *Options → Shortcuts*; \
         the help inside weebshot always shows your current ones."
    };
    format!("# Keyboard shortcuts\n\n{intro}\n{}", keymap.markdown())
}

impl App {
    pub(super) fn docs_window(&mut self, ctx: &egui::Context) {
        if !self.ui.show_docs {
            return;
        }
        let open = super::native_window(
            ctx,
            "docs",
            "weebshot — Documentation",
            [880.0, 660.0],
            [520.0, 320.0],
            |ui| {
                egui::Panel::left("docs_nav")
                    .resizable(false)
                    .exact_size(180.0)
                    .frame(
                        egui::Frame::new()
                            .fill(self.palette.bg1)
                            .inner_margin(egui::Margin::same(8)),
                    )
                    .show(ui, |ui| {
                        for (i, (title, _)) in PAGES.iter().enumerate() {
                            if ui
                                .add_sized(
                                    [164.0, 26.0],
                                    egui::Button::selectable(self.ui.docs_page == i, *title),
                                )
                                .clicked()
                            {
                                self.ui.docs_page = i;
                            }
                        }
                        ui.add_space(12.0);
                        ui.weak(format!("weebshot {}", env!("CARGO_PKG_VERSION")));
                    });
                let page = self.ui.docs_page.min(PAGES.len() - 1);
                let text = if PAGES[page].0 == SHORTCUTS_TITLE {
                    shortcuts_page(&self.settings.keymap, true)
                } else {
                    render(PAGES[page].1, &self.settings.keymap)
                };
                egui::CentralPanel::default()
                    .frame(
                        egui::Frame::new()
                            .fill(self.palette.bg1)
                            .inner_margin(egui::Margin::same(14)),
                    )
                    .show(ui, |ui| {
                        let width = ui.available_width() as usize;
                        egui::ScrollArea::vertical()
                            .id_salt(("docs", page))
                            .auto_shrink(false)
                            .show(ui, |ui| {
                                CommonMarkViewer::new()
                                    .max_image_width(Some(width.saturating_sub(16)))
                                    .show(ui, &mut self.ui.docs_cache, &text);
                            });
                    });
            },
        );
        if !open {
            self.ui.show_docs = false;
        }
    }

    pub(super) fn about_window(&mut self, ctx: &egui::Context) {
        if !self.ui.show_about {
            return;
        }
        let open = super::native_window(
            ctx,
            "about",
            "About weebshot",
            [560.0, 420.0],
            [420.0, 320.0],
            |ui| {
                egui::CentralPanel::default()
                    .frame(
                        egui::Frame::new()
                            .fill(self.palette.bg1)
                            .inner_margin(egui::Margin::same(16)),
                    )
                    .show(ui, |ui| {
                        ui.horizontal_top(|ui| {
                            ui.add(egui::Image::new(MASCOT_URI).max_height(280.0));
                            ui.add_space(12.0);
                            ui.vertical(|ui| {
                                ui.heading(format!("weebshot {}", env!("CARGO_PKG_VERSION")));
                                ui.label("Anime screenshot & clip maker.");
                                ui.add_space(8.0);
                                ui.add(
                                    egui::Label::new(
                                        RichText::new(
                                            "This app was vibecoded — written largely by an AI \
                                             assistant. It works, but use it with that in mind and \
                                             keep backups of anything important.",
                                        )
                                        .color(self.palette.warn),
                                    )
                                    .wrap(),
                                );
                                ui.add_space(8.0);
                                ui.label(RichText::new("Built with").strong());
                                ui.label("libmpv (playback, screenshots)\nffmpeg (exports)\negui (interface)\nPhosphor icons");
                                ui.add_space(4.0);
                                if let Ok(v) = &self.tool_status.ffmpeg {
                                    ui.add(egui::Label::new(RichText::new(v).weak().small()).truncate());
                                }
                                if let Some(v) = &self.tool_status.gifsicle {
                                    ui.add(egui::Label::new(RichText::new(v).weak().small()).truncate());
                                }
                            });
                        });
                    });
            },
        );
        if !open {
            self.ui.show_about = false;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The docs are written with Windows/Linux key names; macOS formats Ctrl as Cmd.
    fn docs_keys(s: &str) -> String {
        s.replace("Cmd+", "Ctrl+")
    }

    #[test]
    fn key_links_match_default_bindings() {
        let km = Keymap::default();
        for (title, src) in PAGES {
            for (_, _, text, target) in links(src) {
                let Some(name) = target.strip_prefix("key:") else {
                    continue;
                };
                let action = action_by_name(name)
                    .unwrap_or_else(|| panic!("{title}: unknown action `{name}`"));
                let binding = docs_keys(
                    &km.get(action)
                        .expect("documented action has a default")
                        .to_string(),
                );
                assert_eq!(
                    text, binding,
                    "{title}: [{text}](key:{name}) doesn't match the default binding"
                );
            }
        }
    }

    #[test]
    fn page_links_point_at_existing_pages() {
        let files = [
            "getting-started.md",
            "install.md",
            "interface.md",
            "timeline.md",
            "screenshots.md",
            "clips.md",
            "gifs.md",
            "shortcuts.md",
            "options.md",
            "troubleshooting.md",
        ];
        for (title, src) in PAGES {
            for (_, _, _, target) in links(src) {
                if target.ends_with(".md") {
                    assert!(files.contains(&target), "{title}: broken link to {target}");
                }
                if let Some(image) = target.strip_prefix("images/") {
                    assert!(
                        DOC_IMAGES.iter().any(|(name, _)| *name == image),
                        "{title}: missing docs/images/{image} (run --docs-screenshots)"
                    );
                }
            }
        }
    }

    /// egui_commonmark overlaps text when a table is nested in a list item.
    #[test]
    fn no_tables_inside_lists() {
        for (title, src) in PAGES {
            for line in src.lines() {
                assert!(
                    !(line.starts_with(' ') && line.trim_start().starts_with('|')),
                    "{title}: indented table row (inside a list?): {line}"
                );
            }
        }
    }

    #[test]
    fn renders_current_bindings() {
        let mut km = Keymap::default();
        km.set(
            Action::Screenshot,
            Some(crate::keymap::Binding::ctrl(egui::Key::P)),
        );
        let out = render("Press [S](key:Screenshot), see [GIFs](gifs.md).", &km);
        assert_eq!(docs_keys(&out), "Press `Ctrl+P`, see **GIFs**.");
    }

    /// docs/shortcuts.md is generated; regenerate with `UPDATE_DOCS=1 cargo test`.
    #[test]
    fn shortcuts_doc_up_to_date() {
        let expected = docs_keys(&shortcuts_page(&Keymap::default(), false));
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/docs/shortcuts.md");
        if std::env::var_os("UPDATE_DOCS").is_some() {
            std::fs::write(path, &expected).unwrap();
        }
        let actual = std::fs::read_to_string(path)
            .unwrap_or_default()
            .replace("\r\n", "\n");
        assert_eq!(
            actual, expected,
            "docs/shortcuts.md is stale: run `UPDATE_DOCS=1 cargo test`"
        );
    }
}
